  1	//! Zilliz-MCP-Server — MCP (Model Context Protocol) server exposing
  2	//! semantic codebase search over the v2rmp Zilliz Cloud vector database.
  3	//!
  4	//! Runs over stdio with JSON-RPC 2.0 framing, one line per message.
  5	//!
  6	//! Tools exposed:
  7	//!   - `search_codebase` — embed a natural-language query via Ollama and
  8	//!     return the top-k code chunks from the v2rmp vector DB.
  9	//!
 10	//! Connect from any MCP client (Claude Desktop, Continue, Cursor, etc.)
 11	//! by adding to the client's config:
 12	//!
 13	//! ```json
 14	//! {
 15	//!   "mcpServers": {
 16	//!     "zilliz-codebase": {
 17	//!       "command": "cargo",
 18	//!       "args": ["run", "--bin", "zilliz-mcp-server", "--release"]
 19	//!     }
 20	//!   }
 21	//! }
 22	//! ```
 23	
 24	use anyhow::{Context, Result};
 25	use serde::{Deserialize, Serialize};
 26	use serde_json::{json, Value};
 27	use std::io::{BufRead, Write};
 28	
 29	// ── Config (same as zilliz_embed_pipeline.py / VECTOR_DB_CONFIG.md) ────────
 30	
 31	const ZILLIZ_URI: &str =
 32	    "https://in05-895d375123308f8.serverless.aws-eu-central-1.cloud.zilliz.com";
 33	fn zilliz_token() -> Result<String> {
 34	    std::env::var("ZILLIZ_TOKEN")
 35	        .context("ZILLIZ_TOKEN environment variable not set")
 36	}
 37	const OLLAMA_URL: &str = "http://localhost:11434/api/embed";
 38	const EMBED_MODEL: &str = "mxbai-embed-large";
 39	const COLLECTION: &str = "v2rmp_codebase";
 40	const DIMENSION: usize = 1024;
 41	
 42	// ── JSON-RPC / MCP types ───────────────────────────────────────────────────
 43	
 44	#[derive(Debug, Deserialize)]
 45	struct Request {
 46	    jsonrpc: String,
 47	    method: String,
 48	    #[serde(default)]
 49	    params: Value,
 50	    #[serde(default)]
 51	    #[allow(dead_code)]
 52	    id: Value,
 53	}
 54	
 55	#[derive(Debug, Serialize)]
 56	struct ToolDef {
 57	    name: String,
 58	    description: String,
 59	    #[serde(rename = "inputSchema")]
 60	    input_schema: Value,
 61	}
 62	
 63	// ── Ollama embed helper ────────────────────────────────────────────────────
 64	
 65	async fn ollama_embed(query: &str) -> Result<Vec<Vec<f32>>> {
 66	    let client = reqwest::Client::new();
 67	    let body = json!({
 68	        "model": EMBED_MODEL,
 69	        "input": [query]
 70	    });
 71	
 72	    let resp = client
 73	        .post(OLLAMA_URL)
 74	        .json(&body)
 75	        .send()
 76	        .await
 77	        .context("Ollama request failed — is it running?")?;
 78	
 79	    let data: Value = resp.json().await.context("Ollama response parse")?;
 80	    let embeddings: Vec<Vec<f32>> =
 81	        serde_json::from_value(data["embeddings"].clone()).context("bad embeddings shape")?;
 82	    Ok(embeddings)
 83	}
 84	
 85	// ── Zilliz REST search ─────────────────────────────────────────────────────
 86	
 87	#[derive(Debug, Deserialize)]
 88	struct ZillizSearchResp {
 89	    data: Vec<ZillizHit>,
 90	}
 91	
 92	#[derive(Debug, Deserialize)]
 93	#[allow(dead_code)]
 94	struct ZillizHit {
 95	    #[serde(default)]
 96	    #[allow(dead_code)]
 97	    id: Value,
 98	    #[serde(default)]
 99	    distance: Option<f64>,
100	    #[serde(default)]
101	    file: Option<String>,
102	    #[serde(default)]
103	    start_line: Option<i64>,
104	    #[serde(default)]
105	    end_line: Option<i64>,
106	    #[serde(default)]
107	    code: Option<String>,
108	}
109	
110	async fn zilliz_search(
111	    vector: &[f32],
112	    limit: usize,
113	) -> Result<Vec<ZillizHit>> {
114	    let client = reqwest::Client::new();
115	
116	    let body = json!({
117	        "collectionName": COLLECTION,
118	        "data": [vector],
119	        "annsField": "vector",
120	        "limit": limit,
121	        "outputFields": ["file", "start_line", "end_line", "code"],
122	        "searchParams": {
123	            "metricType": "L2",
124	            "params": { "nprobe": 32 }
125	        }
126	    });
127	
128	    let resp = client
129	        .post(format!("{ZILLIZ_URI}/v2/vectordb/entities/search"))
130	        .header("Authorization", format!("Bearer {}", zilliz_token()?))
131	        .json(&body)
132	        .send()
133	        .await
134	        .context("Zilliz search request failed")?;
135	
136	    if !resp.status().is_success() {
137	        let status = resp.status();
138	        let text = resp.text().await.unwrap_or_default();
139	        anyhow::bail!("Zilliz returned {status}: {text}");
140	    }
141	
142	    let mut result: ZillizSearchResp =
143	        resp.json().await.context("Zilliz search response parse")?;
144	
145	    Ok(std::mem::take(&mut result.data))
146	}
147	
148	// ── Tool: search_codebase ──────────────────────────────────────────────────
149	
150	async fn handle_search_codebase(args: &Value) -> Result<Value> {
151	    let query = args
152	        .get("query")
153	        .and_then(|v| v.as_str())
154	        .unwrap_or("")
155	        .trim()
156	        .to_string();
157	
158	    if query.is_empty() {
159	        anyhow::bail!("Missing 'query' parameter");
160	    }
161	
162	    let limit = args
163	        .get("limit")
164	        .and_then(|v| v.as_u64())
165	        .unwrap_or(10)
166	        .min(50) as usize;
167	
168	    // 1. Embed
169	    let embeddings = ollama_embed(&query).await?;
170	    let vector = embeddings
171	        .first()
172	        .context("Ollama returned empty embeddings")?;
173	
174	    if vector.len() != DIMENSION {
175	        anyhow::bail!(
176	            "Ollama returned {}-dim embedding; expected {DIMENSION}",
177	            vector.len()
178	        );
179	    }
180	
181	    // 2. Search
182	    let hits = zilliz_search(vector, limit).await?;
183	
184	    // 3. Format
185	    let items: Vec<Value> = hits
186	        .into_iter()
187	        .filter_map(|h| {
188	            Some(json!({
189	                "file": h.file?,
190	                "start_line": h.start_line?,
191	                "end_line": h.end_line?,
192	                "code": h.code?,
193	                "score": h.distance?,
194	            }))
195	        })
196	        .collect();
197	
198	    Ok(json!({
199	        "query": query,
200	        "results": items,
201	        "count": items.len(),
202	        "embedding_model": EMBED_MODEL,
203	        "metric": "L2 (lower = more similar)"
204	    }))
205	}
206	
207	// ── Main loop ──────────────────────────────────────────────────────────────
208	
209	fn send(id: &Value, result: Value) {
210	    let out = json!({
211	        "jsonrpc": "2.0",
212	        "id": id,
213	        "result": result
214	    });
215	    let mut stdout = std::io::stdout().lock();
216	    let _ = writeln!(stdout, "{out}");
217	    let _ = stdout.flush();
218	}
219	
220	fn send_err(id: &Value, code: i64, msg: &str) {
221	    let out = json!({
222	        "jsonrpc": "2.0",
223	        "id": id,
224	        "error": {
225	            "code": code,
226	            "message": msg
227	        }
228	    });
229	    let mut stdout = std::io::stdout().lock();
230	    let _ = writeln!(stdout, "{out}");
231	    let _ = stdout.flush();
232	}
233	
234	#[tokio::main]
235	async fn main() -> Result<()> {
236	    // Stderr for logging so it doesn't corrupt the stdio JSON-RPC stream
237	    eprintln!("zilliz-mcp-server starting (collection={COLLECTION}, model={EMBED_MODEL})");
238	
239	    let stdin = std::io::stdin().lock();
240	    for line in stdin.lines() {
241	        let line = line?;
242	        if line.trim().is_empty() {
243	            continue;
244	        }
245	
246	        let req: Request = match serde_json::from_str(&line) {
247	            Ok(r) => r,
248	            Err(e) => {
249	                send_err(&Value::Null, -32700, &format!("Parse error: {e}"));
250	                continue;
251	            }
252	        };
253	
254	        if req.jsonrpc != "2.0" {
255	            send_err(&req.id, -32600, "Invalid Request: jsonrpc must be 2.0");
256	            continue;
257	        }
258	
259	        match req.method.as_str() {
260	            // ── initialize ────────────────────────────────────────────
261	            "initialize" => {
262	                send(
263	                    &req.id,
264	                    json!({
265	                        "protocolVersion": "2024-11-05",
266	                        "capabilities": {
267	                            "tools": {}
268	                        },
269	                        "serverInfo": {
270	                            "name": "zilliz-mcp-server",
271	                            "version": env!("CARGO_PKG_VERSION")
272	                        }
273	                    }),
274	                );
275	            }
276	
277	            // ── tools/list ────────────────────────────────────────────
278	            "tools/list" => {
279	                let tools = vec![ToolDef {
280	                    name: "search_codebase".into(),
281	                    description: concat!(
282	                        "Semantic search over the v2rmp (rmpca) Rust codebase. ",
283	                        "Embeds your natural-language query with mxbai-embed-large ",
284	                        "and retrieves the most relevant code chunks from the Zilliz ",
285	                        "vector database. Returns file path, line range, code snippet, ",
286	                        "and L2 similarity score for each match."
287	                    ).into(),
288	                    input_schema: json!({
289	                        "type": "object",
290	                        "properties": {
291	                            "query": {
292	                                "type": "string",
293	                                "description": "Natural-language search query, e.g. 'How does the VRP solver optimize routes?'"
294	                            },
295	                            "limit": {
296	                                "type": "integer",
297	                                "description": "Max results (default: 10, max: 50)",
298	                                "default": 10
299	                            }
300	                        },
301	                        "required": ["query"]
302	                    }),
303	                }];
304	                send(&req.id, json!({ "tools": tools }));
305	            }
306	
307	            // ── tools/call ────────────────────────────────────────────
308	            "tools/call" => {
309	                let name = req.params.get("name").and_then(|v| v.as_str()).unwrap_or("");
310	                let args = req.params.get("arguments").cloned().unwrap_or(Value::Null);
311	
312	                match name {
313	                    "search_codebase" => match handle_search_codebase(&args).await {
314	                        Ok(result) => {
315	                            send(
316	                                &req.id,
317	                                json!({
318	                                    "content": [{
319	                                        "type": "text",
320	                                        "text": serde_json::to_string_pretty(&result).unwrap_or_default()
321	                                    }]
322	                                }),
323	                            );
324	                        }
325	                        Err(e) => {
326	                            send(
327	                                &req.id,
328	                                json!({
329	                                    "content": [{
330	                                        "type": "text",
331	                                        "text": format!("Error: {e:#}")
332	                                    }],
333	                                    "isError": true
334	                                }),
335	                            );
336	                        }
337	                    },
338	                    other => {
339	                        send_err(
340	                            &req.id,
341	                            -32602,
342	                            &format!("Unknown tool: {other}"),
343	                        );
344	                    }
345	                }
346	            }
347	
348	            // ── notifications (no response) ───────────────────────────
349	            "notifications/initialized" | "initialized" => {
350	                // No response needed — MCP spec: client sends this after
351	                // receiving the initialize response.
352	            }
353	
354	            // ── unrecognized ──────────────────────────────────────────
355	            other => {
356	                send_err(&req.id, -32601, &format!("Method not found: {other}"));
357	            }
358	        }
359	    }
360	
361	    Ok(())
362	}

   1	//! rmpca-mcp-server — MCP server exposing the route optimization pipeline.
   2	//!
   3	//! Tools: extract_overture, extract_osm, compile, optimize,
   4	//!        clean, vrp_solve, elevation_query, elevation_profile,
   5	//!        predict_solver, score_route, route_embedding, pipeline,
   6	//!        haversine_distance, get_valhalla_matrix, inspect_rmp,
   7	//!        list_solvers, elevation_stats, dem_info, fuel_estimate
   8	//!
   9	//! Runs over stdio with JSON-RPC 2.0 framing (one line per message).
  10	//!
  11	//! Connect from any MCP client by adding to the client config:
  12	//!
  13	//! ```json
  14	//! {
  15	//!   "mcpServers": {
  16	//!     "rmpca": {
  17	//!       "command": "cargo",
  18	//!       "args": ["run", "--bin", "rmpca-mcp-server", "--release"]
  19	//!     }
  20	//!   }
  21	//! }
  22	//! ```
  23	
  24	use anyhow::Result;
  25	use serde::Deserialize;
  26	use serde_json::{json, Value};
  27	use std::io::{BufRead, Write};
  28	use std::path::Path;
  29	use v2rmp::core::clean::{clean_geojson, CleanOptions};
  30	use v2rmp::core::compile::{CompileRequest, CompileResult};
  31	use v2rmp::core::elevation::local::LocalDem;
  32	use v2rmp::core::extract::{BBoxRequest, ExtractRequest, ExtractResult, ExtractSource, RoadClass};
  33	use v2rmp::core::optimize::{
  34	    OnewayMode, OptimizeRequest, OptimizeResult, SolverMode, TurnPenalties,
  35	};
  36	use v2rmp::core::vrp::registry::solve_with;
  37	use v2rmp::core::vrp::types::{
  38	    VRPSolverInput, VRPSolverOutput, VRPSolverStop, VrpObjective,
  39	};
  40	use v2rmp::core::vrp::utils::{build_haversine_matrix, get_valhalla_matrix};
  41	use v2rmp::core::elevation::{FuelCalculator};
  42	#[cfg(feature = "ml")]
  43	use v2rmp::core::ml::features::InstanceFeatures;
  44	#[cfg(feature = "ml")]
  45	use v2rmp::core::ml::selector::{predict_solver, default_model_path};
  46	#[cfg(feature = "ml")]
  47	use v2rmp::core::ml::quality_predictor::{predict_quality};
  48	#[cfg(feature = "ml")]
  49	use v2rmp::core::ml::automl::{predict_hyperparams};
  50	use v2rmp::core::ml_legacy::{RouteFeatures, score_route, route_feature_vector};
  51	#[cfg(feature = "ml")]
  52	use v2rmp::core::nlp::{parse_query, to_vrp_json};
  53	#[cfg(feature = "ml")]
  54	use v2rmp::core::nlp::QwenNLParser;
  55	
  56	// ── JSON-RPC / MCP types ───────────────────────────────────────────────────
  57	
  58	#[derive(Debug, Deserialize)]
  59	struct Request {
  60	    jsonrpc: String,
  61	    method: String,
  62	    #[serde(default)]
  63	    params: Value,
  64	    #[serde(default)]
  65	    id: Value,
  66	}
  67	
  68	#[derive(Debug)]
  69	struct ToolDef {
  70	    name: &'static str,
  71	    description: &'static str,
  72	    input_schema: Value,
  73	}
  74	
  75	// ── Protocol helpers ────────────────────────────────────────────────────────
  76	
  77	fn send(id: &Value, result: Value) {
  78	    let out = json!({
  79	        "jsonrpc": "2.0",
  80	        "id": id,
  81	        "result": result
  82	    });
  83	    let mut stdout = std::io::stdout().lock();
  84	    let _ = writeln!(stdout, "{out}");
  85	    let _ = stdout.flush();
  86	}
  87	
  88	fn send_err(id: &Value, code: i64, msg: &str) {
  89	    let out = json!({
  90	        "jsonrpc": "2.0",
  91	        "id": id,
  92	        "error": { "code": code, "message": msg }
  93	    });
  94	    let mut stdout = std::io::stdout().lock();
  95	    let _ = writeln!(stdout, "{out}");
  96	    let _ = stdout.flush();
  97	}
  98	
  99	fn tool_success(id: &Value, result: &Result<Value>) {
 100	    match result {
 101	        Ok(val) => send(
 102	            id,
 103	            json!({
 104	                "content": [{
 105	                    "type": "text",
 106	                    "text": serde_json::to_string_pretty(val).unwrap_or_default()
 107	                }]
 108	            }),
 109	        ),
 110	        Err(e) => send(
 111	            id,
 112	            json!({
 113	                "content": [{
 114	                    "type": "text",
 115	                    "text": format!("Error: {e:#}")
 116	                }],
 117	                "isError": true
 118	            }),
 119	        ),
 120	    }
 121	}
 122	
 123	// ── Tool definitions ────────────────────────────────────────────────────────
 124	
 125	fn tool_definitions() -> Vec<ToolDef> {
 126	    vec![
 127	        ToolDef {
 128	            name: "extract_overture",
 129	            description: "Extract road network data from Overture Maps S3 Parquet files. \
 130	                Downloads road segments within a bounding box and writes a GeoJSON file. \
 131	                Can take significant time for large bounding boxes.",
 132	            input_schema: json!({
 133	                "type": "object",
 134	                "properties": {
 135	                    "bbox": {
 136	                        "type": "object",
 137	                        "description": "Bounding box: {min_lon, min_lat, max_lon, max_lat}",
 138	                        "properties": {
 139	                            "min_lon": { "type": "number" },
 140	                            "min_lat": { "type": "number" },
 141	                            "max_lon": { "type": "number" },
 142	                            "max_lat": { "type": "number" }
 143	                        },
 144	                        "required": ["min_lon", "min_lat", "max_lon", "max_lat"]
 145	                    },
 146	                    "road_classes": {
 147	                        "type": "array",
 148	                        "description": "Road classes to include (e.g. ['residential','tertiary','secondary']). Default: all vehicle-accessible roads.",
 149	                        "items": { "type": "string" }
 150	                    },
 151	                    "output_path": {
 152	                        "type": "string",
 153	                        "description": "Output GeoJSON file path (default: extract-output.geojson)",
 154	                        "default": "extract-output.geojson"
 155	                    }
 156	                },
 157	                "required": ["bbox"]
 158	            }),
 159	        },
 160	        ToolDef {
 161	            name: "extract_osm",
 162	            description: "Extract road network data from OpenStreetMap. Uses a local PBF file \
 163	                if available, otherwise falls back to the Overpass API. Writes a GeoJSON file.",
 164	            input_schema: json!({
 165	                "type": "object",
 166	                "properties": {
 167	                    "bbox": {
 168	                        "type": "object",
 169	                        "description": "Bounding box: {min_lon, min_lat, max_lon, max_lat}",
 170	                        "properties": {
 171	                            "min_lon": { "type": "number" },
 172	                            "min_lat": { "type": "number" },
 173	                            "max_lon": { "type": "number" },
 174	                            "max_lat": { "type": "number" }
 175	                        },
 176	                        "required": ["min_lon", "min_lat", "max_lon", "max_lat"]
 177	                    },
 178	                    "road_classes": {
 179	                        "type": "array",
 180	                        "description": "Road classes to include. Default: all vehicle-accessible roads.",
 181	                        "items": { "type": "string" }
 182	                    },
 183	                    "pbf_path": {
 184	                        "type": "string",
 185	                        "description": "Path to local OSM PBF file. If omitted, falls back to Overpass API."
 186	                    },
 187	                    "output_path": {
 188	                        "type": "string",
 189	                        "description": "Output GeoJSON file path (default: extract-output.geojson)",
 190	                        "default": "extract-output.geojson"
 191	                    }
 192	                },
 193	                "required": ["bbox"]
 194	            }),
 195	        },
 196	        ToolDef {
 197	            name: "compile",
 198	            description: "Compile a GeoJSON road network file into the binary .rmp format. \
 199	                Optionally runs a cleaning pipeline and prunes disconnected subgraphs.",
 200	            input_schema: json!({
 201	                "type": "object",
 202	                "properties": {
 203	                    "input": {
 204	                        "type": "string",
 205	                        "description": "Path to input GeoJSON file"
 206	                    },
 207	                    "output": {
 208	                        "type": "string",
 209	                        "description": "Path to output .rmp binary file"
 210	                    },
 211	                    "clean": {
 212	                        "type": "boolean",
 213	                        "description": "Run cleaning pipeline before compilation (default: false)",
 214	                        "default": false
 215	                    },
 216	                    "prune_disconnected": {
 217	                        "type": "boolean",
 218	                        "description": "Prune disconnected subgraphs, keeping only the largest (default: false)",
 219	                        "default": false
 220	                    }
 221	                },
 222	                "required": ["input", "output"]
 223	            }),
 224	        },
 225	        ToolDef {
 226	            name: "optimize",
 227	            description: "Run route optimization on a .rmp binary network file. \
 228	                Supports CPP (Chinese Postman — edge coverage) and VRP (Vehicle Routing Problem) modes. \
 229	                Outputs route statistics and optionally writes a GPX file.",
 230	            input_schema: json!({
 231	                "type": "object",
 232	                "properties": {
 233	                    "input": {
 234	                        "type": "string",
 235	                        "description": "Path to input .rmp binary network file"
 236	                    },
 237	                    "output": {
 238	                        "type": "string",
 239	                        "description": "Optional output GPX route file path"
 240	                    },
 241	                    "depot": {
 242	                        "type": "object",
 243	                        "description": "Depot coordinates {lat, lon}. Solver snaps to nearest node.",
 244	                        "properties": {
 245	                            "lat": { "type": "number" },
 246	                            "lon": { "type": "number" }
 247	                        }
 248	                    },
 249	                    "oneway_mode": {
 250	                        "type": "string",
 251	                        "enum": ["respect", "ignore", "reverse"],
 252	                        "description": "How to handle one-way streets (default: respect)",
 253	                        "default": "respect"
 254	                    },
 255	                    "mode": {
 256	                        "type": "string",
 257	                        "enum": ["cpp", "vrp"],
 258	                        "description": "Solver: cpp for edge coverage, vrp for stop visits (default: cpp)",
 259	                        "default": "cpp"
 260	                    },
 261	                    "left_penalty": {
 262	                        "type": "number",
 263	                        "description": "Left turn penalty (default: 1.0)",
 264	                        "default": 1.0
 265	                    },
 266	                    "right_penalty": {
 267	                        "type": "number",
 268	                        "description": "Right turn penalty (default: 0.0)",
 269	                        "default": 0.0
 270	                    },
 271	                    "uturn_penalty": {
 272	                        "type": "number",
 273	                        "description": "U-turn penalty (default: 5.0)",
 274	                        "default": 5.0
 275	                    },
 276	                    "num_vehicles": {
 277	                        "type": "integer",
 278	                        "description": "Number of vehicles — VRP mode only (default: 1)",
 279	                        "default": 1
 280	                    },
 281	                    "solver_id": {
 282	                        "type": "string",
 283	                        "description": "VRP solver algorithm: default, clarke_wright, sweep, two_opt, or_opt",
 284	                        "default": "default"
 285	                    }
 286	                },
 287	                "required": ["input"]
