1603	// ── Inspect RMP handler ──────────────────────────────────────────────────
1604	
1605	fn handle_inspect_rmp(args: &Value) -> Result<Value> {
1606	    let input = args
1607	        .get("input")
1608	        .and_then(|v| v.as_str())
1609	        .ok_or_else(|| anyhow::anyhow!("Missing 'input' parameter"))?;
1610	
1611	    let file_data = std::fs::read(input)
1612	        .map_err(|e| anyhow::anyhow!("Failed to read .rmp file: {}", e))?;
1613	
1614	    let (nodes, edges) = v2rmp::core::optimize::read_rmp_file(&file_data)?;
1615	
1616	    // Compute bounding box from nodes
1617	    let (min_lon, min_lat, max_lon, max_lat) = if nodes.is_empty() {
1618	        (0.0, 0.0, 0.0, 0.0)
1619	    } else {
1620	        nodes.iter().fold(
1621	            (f64::MAX, f64::MAX, f64::MIN, f64::MIN),
1622	            |(mn_lon, mn_lat, mx_lon, mx_lat), n| {
1623	                (mn_lon.min(n.lon), mn_lat.min(n.lat), mx_lon.max(n.lon), mx_lat.max(n.lat))
1624	            },
1625	        )
1626	    };
1627	
1628	    let total_edge_length_km: f64 = edges.iter().map(|e| e.weight_m / 1000.0).sum();
1629	
1630	    Ok(json!({
1631	        "node_count": nodes.len(),
1632	        "edge_count": edges.len(),
1633	        "bbox": {
1634	            "min_lat": min_lat,
1635	            "max_lat": max_lat,
1636	            "min_lon": min_lon,
1637	            "max_lon": max_lon,
1638	        },
1639	        "total_edge_length_km": total_edge_length_km,
1640	        "file_size_bytes": file_data.len(),
1641	    }))
1642	}
