64	/// Build a distance matrix using shortest paths on the road network graph.
65	pub fn build_graph_matrix(
66	    stops: &[VRPSolverStop],
67	    nodes: &[RmpNode],
68	    edges: &[RmpEdge],
69	    embeddings: Option<EmbeddingsSlice>,
70	    avg_speed_kmh: f64,
71	) -> DistMatrix {
72	    let n_stops = stops.len();
73	    let n_nodes = nodes.len();
74	    if n_stops == 0 || n_nodes == 0 {
75	        return vec![vec![DistCell { distance: 0.0, time: 0.0 }; n_stops]; n_stops];
76	    }
77	
78	    // 1. Build adjacency list
79	    let mut adj = vec![Vec::new(); n_nodes];
80	    for (i, edge) in edges.iter().enumerate() {
81	        let mut weight = edge.weight_m;
82	        
83	        // Apply learned embedding if available
84	        #[cfg(feature = "ml")]
85	        if let Some(embs) = embeddings {
86	            if let Some(emb) = embs.get(i) {
87	                // Use first dimension as a learned bias for now
88	                // Research basis: GAIN (2107.07791)
89	                let bias = emb.vector.get(0).copied().unwrap_or(0.0);
90	                weight *= (1.0 + bias as f64).max(0.1_f64);
91	            }
92	        }
93	
94	        adj[edge.from as usize].push((edge.to as usize, weight));
