151	    fn test_predict_quality_fallback() {
152	        let stops = vec![
153	            make_stop(0.0, 0.0, "depot"),
154	            make_stop(1.0, 0.0, "a"),
155	            make_stop(0.0, 1.0, "b"),
156	        ];
157	        let input = make_input(stops, 1);
158	        let features = InstanceFeatures::from_input(&input);
159	        let pred = predict_quality(&features);
160	        assert!(pred.predicted_gap_pct >= 0.0 && pred.predicted_gap_pct <= 50.0);
161	        assert!(pred.predicted_tour_length_km >= 0.0);
162	    }
163	}

  1	//! Instance-aware AutoML hyperparameter tuner.
  2	//!
  3	//! Predicts solver hyperparameters from instance features using
  4	//! Ridge regression or a small multi-output MLP.
  5	//!
  6	//! Research basis: Instance-Aware Parameter Configuration (2605.00572, 2026)
  7	
  8	use crate::core::ml::features::InstanceFeatures;
  9	pub use crate::core::vrp::types::SolverHyperparams;
 10	use anyhow::{Context, Result};
 11	use candle_core::{Device, DType, Tensor};
 12	use candle_nn::{linear, Linear, Module, VarBuilder};
 13	use std::path::Path;
 14	
 15	const NUM_FEATURES: usize = 28;
 16	const HIDDEN1: usize = 64;
 17	const NUM_OUTPUTS: usize = 5;
 18	
 19	/// Learned multi-output MLP hyperparameter predictor.
 20	pub struct HyperparamPredictor {
 21	    lin1: Linear,
 22	    lin2: Linear,
 23	    device: Device,
 24	}
 25	
 26	impl HyperparamPredictor {
 27	    /// Load from a safetensors file.
 28	    pub fn from_file(path: &Path) -> Result<Self> {
 29	        let device = crate::core::ml::best_device()?;
 30	        let tensors = candle_core::safetensors::load(path, &device)
 31	            .with_context(|| format!("Failed to load safetensors from {}", path.display()))?;
 32	        let vb = VarBuilder::from_tensors(tensors, DType::F32, &device);
 33	        let lin1 = linear(NUM_FEATURES, HIDDEN1, vb.pp("lin1"))?;
 34	        let lin2 = linear(HIDDEN1, NUM_OUTPUTS, vb.pp("lin2"))?;
 35	        Ok(Self { lin1, lin2, device })
 36	    }
 37	
 38	    /// Predict hyperparameters from instance features.
 39	    pub fn predict(&self, features: &InstanceFeatures) -> Result<SolverHyperparams> {
 40	        let x = features.to_vector();
 41	        let input = Tensor::from_vec(x, (1, NUM_FEATURES), &self.device)?;
 42	        let h1 = self.lin1.forward(&input)?.relu()?;
 43	        let out = self.lin2.forward(&h1)?;
 44	        let vals: Vec<f32> = out.squeeze(0)?.to_vec1()?;
 45	        let v = vals.as_slice();
 46	
 47	        // Clamp each output to [0, 1] and scale to parameter range
 48	        let max_iter = (100.0 + v[0].clamp(0.0, 1.0) as f64 * 9900.0) as u32;
 49	        let temperature = 1.0 + v[1].clamp(0.0, 1.0) as f64 * 999.0;
 50	        let tabu_tenure = (1.0 + v[2].clamp(0.0, 1.0) as f64 * 49.0).round() as usize;
 51	        let cooling_rate = 0.8 + v[3].clamp(0.0, 1.0) as f64 * 0.199;
 52	        let neighbourhood_radius = (1.0 + v[4].clamp(0.0, 1.0) as f64 * 19.0).round() as usize;
 53	
 54	        Ok(SolverHyperparams {
 55	            max_iterations: max_iter,
 56	            temperature,
 57	            tabu_tenure,
 58	            cooling_rate,
 59	            neighbourhood_radius,
 60	            model_used: true,
 61	        })
 62	    }
 63	}
