461	
462	    #[test]
463	    fn test_features_vector_length() {
464	        let stops = vec![
465	            make_stop(0.0, 0.0, "depot"),
466	            make_stop(1.0, 0.0, "a"),
467	            make_stop(0.0, 1.0, "b"),
