133	fn dijkstra(start: usize, adj: &[Vec<(usize, f64)>], n: usize) -> Vec<f64> {
134	    use std::collections::BinaryHeap;
135	    use std::cmp::Ordering;
136	
137	    #[derive(Copy, Clone, PartialEq)]
138	    struct State {
139	        cost: f64,
140	        position: usize,
141	    }
142	    impl Eq for State {}
143	    impl Ord for State {
144	        fn cmp(&self, other: &Self) -> Ordering {
145	            other.cost.partial_cmp(&self.cost).unwrap_or(Ordering::Equal)
146	        }
147	    }
148	    impl PartialOrd for State {
149	        fn partial_cmp(&self, other: &Self) -> Option<Ordering> {
