191	    let client = reqwest::Client::new();
192	    let resp = client
193	        .post(url)
194	        .json(&body)
195	        .send()
196	        .await
197	        .map_err(|e| format!("Valhalla request failed: {e}"))?;
198	
199	    if !resp.status().is_success() {
200	        return Err(format!("Valhalla HTTP {}", resp.status()));
201	    }
202	
203	    let data: serde_json::Value = resp
204	        .json()
205	        .await
206	        .map_err(|e| format!("Valhalla parse error: {e}"))?;
207	
208	    let stt = data
209	        .get("sources_to_targets")
210	        .ok_or("Invalid Valhalla response: missing sources_to_targets")?;
211	
212	    let rows = stt
213	        .as_array()
214	        .ok_or("Invalid Valhalla response: sources_to_targets not an array")?;
215	    let n = rows.len();
216	    let mut matrix = Vec::with_capacity(n);
217	    for row_val in rows {
218	        let row = row_val.as_array().ok_or("Invalid Valhalla row")?;
219	        let mut matrix_row = Vec::with_capacity(n);
220	        for cell_val in row {
221	            let cell = cell_val.as_object();
222	            let (dist, time) = match cell {
223	                Some(c) => (
224	                    c.get("distance").and_then(|v| v.as_f64()).unwrap_or(0.0),
225	                    c.get("time").and_then(|v| v.as_f64()).unwrap_or(0.0),
226	                ),
227	                None => (0.0, 0.0),
228	            };
229	            matrix_row.push(DistCell {
230	                distance: dist,
231	                time,
232	            });
233	        }
234	        matrix.push(matrix_row);
235	    }
236	    Ok(matrix)
237	}
