  56	// ── JSON-RPC / MCP types ───────────────────────────────────────────────────
  57	
  58	#[derive(Debug, Deserialize)]
  59	struct Request {
  60	    jsonrpc: String,
  61	    method: String,
  62	    #[serde(default)]
  63	    params: Value,
  64	    #[serde(default)]
  65	    id: Value,
  66	}
  67	
  68	#[derive(Debug)]
  69	struct ToolDef {
  70	    name: &'static str,
  71	    description: &'static str,
  72	    input_schema: Value,
  73	}
  74	
  75	// ── Protocol helpers ────────────────────────────────────────────────────────
  76	
  77	fn send(id: &Value, result: Value) {
  78	    let out = json!({
  79	        "jsonrpc": "2.0",
  80	        "id": id,
  81	        "result": result
  82	    });
  83	    let mut stdout = std::io::stdout().lock();
  84	    let _ = writeln!(stdout, "{out}");
  85	    let _ = stdout.flush();
  86	}
  87	
  88	fn send_err(id: &Value, code: i64, msg: &str) {
  89	    let out = json!({
  90	        "jsonrpc": "2.0",
  91	        "id": id,
  92	        "error": { "code": code, "message": msg }
  93	    });
  94	    let mut stdout = std::io::stdout().lock();
  95	    let _ = writeln!(stdout, "{out}");
  96	    let _ = stdout.flush();
  97	}
  98	
  99	fn tool_success(id: &Value, result: &Result<Value>) {
 100	    match result {
 101	        Ok(val) => send(
 102	            id,
 103	            json!({
 104	                "content": [{
 105	                    "type": "text",
 106	                    "text": serde_json::to_string_pretty(val).unwrap_or_default()
 107	                }]
 108	            }),
 109	        ),
 110	        Err(e) => send(
 111	            id,
 112	            json!({
 113	                "content": [{
 114	                    "type": "text",
 115	                    "text": format!("Error: {e:#}")
 116	                }],
 117	                "isError": true
 118	            }),
 119	        ),
 120	    }
 121	}
