 912	fn parse_bbox(args: &Value) -> anyhow::Result<BBoxRequest> {
 913	    let bbox = args
 914	        .get("bbox")
 915	        .ok_or_else(|| anyhow::anyhow!("Missing 'bbox' parameter"))?;
 916	    Ok(BBoxRequest {
 917	        min_lon: bbox
 918	            .get("min_lon")
 919	            .and_then(|v| v.as_f64())
 920	            .ok_or_else(|| anyhow::anyhow!("bbox.min_lon required"))?,
 921	        min_lat: bbox
 922	            .get("min_lat")
 923	            .and_then(|v| v.as_f64())
 924	            .ok_or_else(|| anyhow::anyhow!("bbox.min_lat required"))?,
 925	        max_lon: bbox
 926	            .get("max_lon")
 927	            .and_then(|v| v.as_f64())
 928	            .ok_or_else(|| anyhow::anyhow!("bbox.max_lon required"))?,
 929	        max_lat: bbox
 930	            .get("max_lat")
 931	            .and_then(|v| v.as_f64())
 932	            .ok_or_else(|| anyhow::anyhow!("bbox.max_lat required"))?,
 933	    })
 934	}
 935	
 936	fn parse_road_classes(args: &Value) -> Vec<RoadClass> {
 937	    let Some(arr) = args.get("road_classes").and_then(|v| v.as_array()) else {
 938	        return RoadClass::all_vehicle();
 939	    };
 940	    if arr.is_empty() {
 941	        return RoadClass::all_vehicle();
 942	    }
 943	    arr.iter()
 944	        .filter_map(|v| v.as_str())
 945	        .filter_map(|s| match s {
 946	            "residential" => Some(RoadClass::Residential),
 947	            "tertiary" => Some(RoadClass::Tertiary),
 948	            "secondary" => Some(RoadClass::Secondary),
 949	            "primary" => Some(RoadClass::Primary),
 950	            "trunk" => Some(RoadClass::Trunk),
 951	            "motorway" => Some(RoadClass::Motorway),
 952	            "unclassified" => Some(RoadClass::Unclassified),
 953	            "living_street" => Some(RoadClass::LivingStreet),
 954	            "service" => Some(RoadClass::Service),
 955	            "secondary_link" => Some(RoadClass::SecondaryLink),
 956	            "primary_link" => Some(RoadClass::PrimaryLink),
 957	            "trunk_link" => Some(RoadClass::TrunkLink),
 958	            "motorway_link" => Some(RoadClass::MotorwayLink),
 959	            _ => None,
 960	        })
 961	        .collect()
 962	}
 963	
 964	fn parse_oneway_mode(args: &Value) -> OnewayMode {
 965	    match args
 966	        .get("oneway_mode")
 967	        .and_then(|v| v.as_str())
 968	        .unwrap_or("respect")
 969	    {
 970	        "ignore" => OnewayMode::Ignore,
 971	        "reverse" => OnewayMode::Reverse,
 972	        _ => OnewayMode::Respect,
 973	    }
 974	}
 975	
 976	fn parse_solver_mode(args: &Value) -> SolverMode {
 977	    match args
 978	        .get("mode")
 979	        .and_then(|v| v.as_str())
 980	        .unwrap_or("cpp")
 981	    {
 982	        "vrp" => SolverMode::Vrp,
 983	        _ => SolverMode::Cpp,
 984	    }
 985	}
