 989	async fn handle_extract_overture(args: &Value) -> Result<Value> {
 990	    let bbox = parse_bbox(args)?;
 991	    let road_classes = parse_road_classes(args);
 992	    let output_path = args
 993	        .get("output_path")
 994	        .and_then(|v| v.as_str())
 995	        .unwrap_or("extract-output.geojson")
 996	        .to_string();
 997	
 998	    tracing::info!("extract_overture: bbox={:.4},{:.4},{:.4},{:.4}",
 999	        bbox.min_lon, bbox.min_lat, bbox.max_lon, bbox.max_lat);
1000	
1001	    let req = ExtractRequest {
1002	        source: ExtractSource::Overture,
1003	        bbox,
1004	        road_classes,
1005	        output_path,
1006	        pbf_path: None,
1007	    };
1008	
1009	    let result: ExtractResult = v2rmp::core::extract::run_extract(&req).await?;
1010	    Ok(serde_json::to_value(result)?)
1011	}
