1038	fn handle_compile(args: &Value) -> Result<Value> {
1039	    let input = args
1040	        .get("input")
1041	        .and_then(|v| v.as_str())
1042	        .ok_or_else(|| anyhow::anyhow!("Missing 'input' parameter"))?
1043	        .to_string();
1044	    let output = args
1045	        .get("output")
1046	        .and_then(|v| v.as_str())
1047	        .ok_or_else(|| anyhow::anyhow!("Missing 'output' parameter"))?
1048	        .to_string();
1049	    let clean = args
1050	        .get("clean")
1051	        .and_then(|v| v.as_bool())
1052	        .unwrap_or(false);
1053	    let prune = args
1054	        .get("prune_disconnected")
1055	        .and_then(|v| v.as_bool())
1056	        .unwrap_or(false);
1057	
1058	    let clean_options = if clean {
1059	        Some(v2rmp::core::clean::CleanOptions::default())
1060	    } else {
1061	        None
1062	    };
1063	
1064	    tracing::info!("compile: {} -> {}", input, output);
1065	
1066	    let req = CompileRequest {
1067	        input_geojson: input,
1068	        output_rmp: output,
1069	        compress: false,
1070	        road_classes: vec![],
1071	        clean_options,
1072	        prune_disconnected: prune,
1073	    };
1074	
1075	    let result: CompileResult = v2rmp::core::compile::run_compile(&req)?;
1076	    Ok(serde_json::to_value(result)?)
1077	}
