1553	    if samples_val.len() < 2 {
1554	        anyhow::bail!("At least 2 samples are required for fuel estimation");
1555	    }
1556	
1557	    let base_consumption = args
1558	        .get("base_consumption")
1559	        .and_then(|v| v.as_f64())
1560	        .unwrap_or(0.08);
1561	
1562	    // Build an ElevationProfile from the samples
1563	    let points: Vec<v2rmp::core::elevation::RouteElevationPoint> = samples_val
1564	        .iter()
1565	        .enumerate()
1566	        .map(|(i, s)| {
1567	            let distance_m = s.get("distance_m").and_then(|v| v.as_f64())
1568	                .ok_or_else(|| anyhow::anyhow!("Sample {} missing 'distance_m'", i))?;
1569	            let elevation_m = s.get("elevation_m").and_then(|v| v.as_f64())
1570	                .ok_or_else(|| anyhow::anyhow!("Sample {} missing 'elevation_m'", i))?;
1571	            Ok(v2rmp::core::elevation::RouteElevationPoint {
1572	                distance_m,
1573	                elevation_m: Some(elevation_m),
1574	                point: v2rmp::core::elevation::Point { lon: 0.0, lat: 0.0 },
1575	            })
1576	        })
1577	        .collect::<Result<Vec<_>>>()?;
1578	
1579	    let total_distance_km = points.last().map(|p| p.distance_m / 1000.0).unwrap_or(0.0);
1580	
1581	    let profile = v2rmp::core::elevation::ElevationProfile {
1582	        points,
1583	        total_ascent: 0.0, // Not needed for fuel calc
1584	        total_descent: 0.0,
1585	        max_elevation: 0.0,
1586	        min_elevation: 0.0,
1587	        avg_elevation: 0.0,
1588	        distance_km: total_distance_km,
1589	    };
1590	
1591	    let consumption = FuelCalculator::calculate(&profile, base_consumption);
1592	
1593	    Ok(json!({
1594	        "total_fuel_l": consumption.total_fuel_l,
1595	        "avg_consumption_l_per_km": consumption.avg_consumption_l_per_km,
1596	        "elevation_penalty_l": consumption.elevation_penalty_l,
1597	        "elevation_benefit_l": consumption.elevation_benefit_l,
1598	        "base_consumption_l_per_km": base_consumption,
1599	        "distance_km": total_distance_km,
1600	    }))
1601	}
