1878	// ── Pipeline handler ─────────────────────────────────────────────────────
1879	
1880	async fn handle_pipeline(args: &Value) -> Result<Value> {
1881	    let bbox = parse_bbox(args)?;
1882	    let output_dir = args
1883	        .get("output_dir")
1884	        .and_then(|v| v.as_str())
1885	        .unwrap_or("./pipeline-output")
1886	        .to_string();
1887	    let source = match args.get("source").and_then(|v| v.as_str()).unwrap_or("overture") {
1888	        "osm" => ExtractSource::Osm,
1889	        _ => ExtractSource::Overture,
1890	    };
1891	    let pbf_path = args.get("pbf_path").and_then(|v| v.as_str()).map(String::from);
1892	    let depot = args.get("depot").and_then(|d| {
1893	        let lat = d.get("lat")?.as_f64()?;
1894	        let lon = d.get("lon")?.as_f64()?;
1895	        Some((lat, lon))
1896	    });
1897	    let mode = parse_solver_mode(args);
1898	    let prune_disconnected = args.get("prune_disconnected").and_then(|v| v.as_bool()).unwrap_or(false);
1899	
1900	    // Ensure output directory exists
1901	    std::fs::create_dir_all(&output_dir)?;
1902	
1903	    let extract_path = format!("{}/extract.geojson", output_dir);
1904	    let cleaned_path = format!("{}/cleaned.geojson", output_dir);
1905	    let rmp_path = format!("{}/network.rmp", output_dir);
1906	    let route_path = format!("{}/route.gpx", output_dir);
1907	
1908	    // Stage 1: Extract
1909	    tracing::info!("pipeline stage 1: extract");
1910	    let extract_req = ExtractRequest {
1911	        source,
1912	        bbox,
1913	        road_classes: RoadClass::all_vehicle(),
1914	        output_path: extract_path.clone(),
1915	        pbf_path,
1916	    };
1917	    let extract_result = v2rmp::core::extract::run_extract(&extract_req).await?;
1918	
1919	    // Stage 2: Clean
1920	    tracing::info!("pipeline stage 2: clean");
1921	    let input_data = std::fs::read_to_string(&extract_path)?;
1922	    let geojson: geojson::FeatureCollection = serde_json::from_str(&input_data)?;
1923	    let (cleaned, clean_stats, _warnings) = clean_geojson(&geojson, &CleanOptions::default())?;
1924	    let cleaned_str = serde_json::to_string_pretty(&cleaned)?;
1925	    std::fs::write(&cleaned_path, &cleaned_str)?;
1926	
1927	    // Stage 3: Compile
1928	    tracing::info!("pipeline stage 3: compile");
1929	    let compile_req = CompileRequest {
1930	        input_geojson: cleaned_path.clone(),
1931	        output_rmp: rmp_path.clone(),
1932	        compress: false,
1933	        road_classes: vec![],
1934	        clean_options: None,
1935	        prune_disconnected,
1936	    };
1937	    let compile_result = v2rmp::core::compile::run_compile(&compile_req)?;
1938	
1939	    // Stage 4: Optimize
1940	    tracing::info!("pipeline stage 4: optimize");
1941	    let num_vehicles = args.get("num_vehicles").and_then(|v| v.as_u64()).unwrap_or(1) as usize;
1942	    let solver_id = args.get("solver_id").and_then(|v| v.as_str()).unwrap_or("clarke_wright").to_string();
1943	let optimize_req = OptimizeRequest {
1944	    cache_file: rmp_path.clone(),
1945	    route_file: Some(route_path.clone()),
1946	    turn_penalties: TurnPenalties::default(),
1947	    depot,
1948	    oneway_mode: OnewayMode::default(),
1949	    mode,
1950	    num_vehicles,
1951	    solver_id,
1952	    coordinates: None,
1953	};
1954	    let optimize_result = v2rmp::core::optimize::run_optimize(&optimize_req).await?;
1955	
1956	    Ok(json!({
1957	        "output_dir": output_dir,
1958	        "extract": {
1959	            "nodes": extract_result.nodes,
1960	            "edges": extract_result.edges,
1961	            "total_km": extract_result.total_km,
1962	        },
1963	        "clean": {
1964	            "input_features": clean_stats.input_features,
1965	            "output_features": clean_stats.output_features,
1966	            "total_removed": clean_stats.total_removed(),
1967	        },
1968	        "compile": {
1969	            "node_count": compile_result.node_count,
1970	            "edge_count": compile_result.edge_count,
1971	            "output_size_bytes": compile_result.output_size_bytes,
1972	        },
1973	        "optimize": {
1974	            "total_distance_km": optimize_result.total_distance_km,
1975	            "total_segments": optimize_result.total_segments,
1976	            "deadhead_distance_km": optimize_result.deadhead_distance_km,
1977	            "efficiency_pct": optimize_result.efficiency_pct,
1978	            "num_routes": optimize_result.num_routes,
1979	        },
1980	    }))
1981	}
