133	fn dijkstra(start: usize, adj: &[Vec<(usize, f64)>], n: usize) -> Vec<f64> {
134	    use std::collections::BinaryHeap;
135	    use std::cmp::Ordering;
136	
137	    #[derive(Copy, Clone, PartialEq)]
138	    struct State {
139	        cost: f64,
140	        position: usize,
141	    }
142	    impl Eq for State {}
143	    impl Ord for State {
144	        fn cmp(&self, other: &Self) -> Ordering {
145	            other.cost.partial_cmp(&self.cost).unwrap_or(Ordering::Equal)
146	        }
147	    }
148	    impl PartialOrd for State {
149	        fn partial_cmp(&self, other: &Self) -> Option<Ordering> {
150	            Some(self.cmp(other))
151	        }
152	    }
153	
154	    let mut dists = vec![f64::MAX; n];
155	    let mut heap = BinaryHeap::new();
156	
157	    dists[start] = 0.0;
158	    heap.push(State { cost: 0.0, position: start });
159	
160	    while let Some(State { cost, position }) = heap.pop() {
161	        if cost > dists[position] { continue; }
162	
163	        for (next, weight) in &adj[position] {
164	            let next_cost = cost + weight;
165	            if next_cost < dists[*next] {
166	                dists[*next] = next_cost;
167	                heap.push(State { cost: next_cost, position: *next });
168	            }
169	        }
170	    }
171	    dists
172	}
