 39	    /// Extract road network from Overpass API with endpoint fallback
 40	    pub async fn extract_bbox(&self, bbox: &BBox, road_classes: &[String]) -> Result<Vec<OsmSegment>> {
 41	        let classes_filter = if road_classes.is_empty() {
 42	            "way[\"highway\"]".to_string()
 43	        } else {
 44	            format!("way[\"highway\"~\"^{}$\"]", road_classes.join("|"))
 45	        };
 46	
 47	        // Overpass QL query:
 48	        // 1. Set output format and timeout
 49	        // 2. Query ways with highway tag in bbox
 50	        // 3. Recurse down to get nodes (>)
 51	        // 4. Output body and skeleton
 52	        let query = format!(
 53	            "[out:json][timeout:300];\n(\n  {}({},{},{},{});\n);\nout body;\n>;\nout skel qt;",
 54	            classes_filter,
 55	            bbox.min_lat, bbox.min_lon, bbox.max_lat, bbox.max_lon
 56	        );
 57	
 58	        let mut last_error = None;
 59	
 60	        for endpoint in OVERPASS_ENDPOINTS {
 61	            tracing::info!("Attempting Overpass extraction from: {}", endpoint);
 62	            match self.query_endpoint(endpoint, &query).await {
 63	                Ok(segments) => {
 64	                    tracing::info!("Successfully extracted {} segments from {}", segments.len(), endpoint);
 65	                    return Ok(segments);
 66	                }
 67	                Err(e) => {
 68	                    tracing::warn!("Overpass endpoint {} failed: {:#}", endpoint, e);
 69	                    last_error = Some(e);
 70	                    // Continue to next endpoint
 71	                }
 72	            }
 73	        }
 74	
 75	        Err(last_error.unwrap_or_else(|| anyhow::anyhow!("All Overpass endpoints failed")))
 76	    }
