 78	    async fn query_endpoint(&self, endpoint: &str, query: &str) -> Result<Vec<OsmSegment>> {
 79	        let response = self.client
 80	            .post(endpoint)
 81	            .form(&[("data", query)])
 82	            .send()
 83	            .await
 84	            .with_context(|| format!("Failed to connect to Overpass endpoint: {}", endpoint))?;
 85	
 86	        if !response.status().is_success() {
 87	            let status = response.status();
 88	            let error_text = response.text().await.unwrap_or_else(|_| "Unknown error".to_string());
 89	            anyhow::bail!("Overpass endpoint {} returned error {}: {}", endpoint, status, error_text);
 90	        }
 91	
 92	        let data: Value = response.json().await
 93	            .with_context(|| format!("Failed to parse JSON response from {}", endpoint))?;
 94	
 95	        self.parse_overpass_json(data)
 96	    }
