 56	/// Main cleaning pipeline: GeoJSON -> cleaned GeoJSON
 57	pub fn clean_geojson(
 58	    geojson: &geojson::FeatureCollection,
 59	    options: &CleanOptions,
 60	) -> Result<(geojson::FeatureCollection, CleanStats, Vec<String>)> {
 61	    let mut stats = CleanStats::default();
 62	    let mut warnings = Vec::new();
 63	    stats.input_features = geojson.features.len();
 64	
 65	    // Stage 1: Repair geometries
 66	    let (repaired, point_features) =
 67	        geometry::repair_features(&geojson.features, options, &mut stats)?;
 68	
 69	    if repaired.is_empty() && point_features.is_empty() {
 70	        return Ok((
 71	            geojson::FeatureCollection {
 72	                bbox: None,
 73	                features: vec![],
 74	                foreign_members: None,
 75	            },
 76	            stats,
 77	            warnings,
 78	        ));
 79	    }
 80	
 81	    // Check for high invalid drop ratio
 82	    if stats.input_features > 0 {
 83	        let drop_ratio = stats.invalid_dropped as f64 / stats.input_features as f64;
 84	        if drop_ratio > 0.10 {
 85	            let msg = format!(
 86	                "Over 10% of features were dropped as invalid ({}/{} = {:.1}%). \
 87	                 Consider checking CRS and geometry validity.",
 88	                stats.invalid_dropped,
 89	                stats.input_features,
 90	                drop_ratio * 100.0
 91	            );
 92	            warnings.push(msg);
 93	        }
 94	    }
 95	
 96	    // Stage 2: Build graph (only from LineString features, not points)
 97	    let mut graph = graph::build_graph(&repaired, options.node_precision_decimals)?;
 98	
 99	    // Stages 3–11
100	    if options.remove_selfloops {
101	        stats.selfloops_removed = graph::remove_selfloops(&mut graph);
102	    }
103	
104	    if options.min_length_m > 0.0 {
105	        stats.short_edges_removed = graph::remove_short_edges(&mut graph, options.min_length_m);
106	    }
107	
108	    if options.node_snap_m > 0.0 {
109	        stats.nodes_merged = spatial::merge_nearby_nodes(
110	            &mut graph,
111	            options.node_snap_m,
112	            options.node_precision_decimals,
113	            options.merge_node_positions,
114	        )?;
115	    }
116	
117	    if options.dedupe_edges {
118	        stats.duplicate_edges_removed = graph::dedupe_edges(&mut graph);
119	    }
120	
121	    if let Some(ref attrs) = options.required_attrs {
122	        stats.incomplete_edges_removed = graph::remove_edges_missing_attrs(&mut graph, attrs);
123	    }
124	
125	    if options.merge_parallel_edges {
126	        let merge_props =
127	            options.property_merge_strategy == "merge" || options.merge_parallel_edge_properties;
128	        stats.parallel_edges_merged = graph::merge_parallel_edges(&mut graph, merge_props);
129	    }
130	
131	    if options.remove_isolates {
132	        stats.isolates_removed = graph::remove_isolates(&mut graph);
133	    }
134

134	
135	    if options.max_components > 0 {
136	        stats.components_removed =
137	            graph::keep_largest_components(&mut graph, options.max_components);
138	    }
139	
140	    // Stage 4: Export to GeoJSON (include point features if requested)
141	    let point_ref = if options.include_points {
142	        Some(point_features.as_slice())
143	    } else {
144	        None
145	    };
146	    let cleaned = graph::graph_to_geojson(&graph, options.simplify_tolerance_m, point_ref)?;
147	    stats.output_features = cleaned.features.len();
